<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute } from 'vue-router';
import { api, errorMessage } from '../services/api';
import { useClub } from '../stores/club';
import StatChart from '../components/StatChart.vue';
import StateNotice from '../components/StateNotice.vue';
const route = useRoute(), club = useClub(); const player = ref<any>(), stats = ref<any>(), reports = ref<any[]>([]), seasons = ref<any[]>([]), error = ref(''), busy = ref(false), message = ref(''), rating = ref(7), notes = ref(''), seasonId = ref('');
const params = computed(() => typeof route.query.organizationId === 'string' ? { organizationId: route.query.organizationId } : {});
const canEvaluate = computed(() => params.value.organizationId === club.selectedId && club.can('analysis:write'));
async function load() { busy.value = true; error.value = ''; try { const id = route.params.id; const [p, s, r, seasonsResponse] = await Promise.all([api.get(`/players/${id}`, { params: params.value }), api.get(`/statistics/players/${id}`, { params: { ...params.value, ...(seasonId.value ? { seasonId: seasonId.value } : {}) } }), api.get(`/players/${id}/evaluations`, { params: params.value }), api.get('/competitions/seasons', { params: params.value })]); player.value = p.data; stats.value = s.data; reports.value = r.data; seasons.value = seasonsResponse.data; } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function evaluate() { try { await api.post('/players/evaluations', { playerId: route.params.id, seasonId: seasonId.value, rating: rating.value, notes: notes.value }, { params: params.value }); message.value = 'Evaluación guardada'; notes.value = ''; await load(); } catch (e) { error.value = errorMessage(e); } }
async function favorite() { try { await api.post('/favorites', { playerId: route.params.id }); message.value = 'Jugador guardado en favoritos'; } catch (e) { error.value = errorMessage(e); } }
onMounted(load);
</script>
<template><section><button class="button subtle back" @click="$router.back()"><i aria-hidden="true" class="pi pi-arrow-left" /> Volver</button><StateNotice :loading="busy" :error="error" @retry="load" /><template v-if="player && stats && !busy && !error"><div v-if="player.isDemo" class="demo-banner">Perfil ficticio de demostración</div><div class="player-profile"><div class="profile-avatar">{{ player.name.split(' ').map((v: string) => v[0]).slice(0, 2).join('') }}</div><div><span class="eyebrow">PERFIL DE JUGADOR / {{ player.source }}</span><h1>{{ player.name }}</h1><p>{{ player.position }} · {{ player.nationality ?? 'Nacionalidad no disponible' }}</p><span v-if="player.birthDate" class="muted">Nacimiento: {{ player.birthDate.slice(0, 10) }}</span></div><button class="button subtle" @click="favorite"><i aria-hidden="true" class="pi pi-star" /> Favorito</button></div><div v-if="message" class="alert success">{{ message }}</div><div class="filter-bar"><select v-model="seasonId" aria-label="Temporada" @change="load"><option value="">Todas las temporadas</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></div><div class="metric-grid"><div v-for="m in [['Participaciones', stats.appearances], ['Minutos registrados', stats.minutes], ['Goles registrados', stats.goals], ['Goles / 90', stats.goalsPer90]]" :key="m[0]" class="metric-card"><span>{{ m[0] }}</span><strong>{{ m[1] ?? '—' }}</strong></div></div><p class="chart-footnote">{{ stats.coverage }}</p><div class="dashboard-grid"><section class="panel"><h2>Evolución</h2><StatChart v-if="stats.evolution.length" type="line" :labels="stats.evolution.map((e: any) => new Date(e.date).toLocaleDateString('es'))" :series="[{ name: 'Goles registrados', data: stats.evolution.map((e: any) => e.goals) }]" /><StateNotice v-else empty /></section><section class="panel"><h2>Historial de equipos</h2><div v-for="s in player.squads" :key="s.id" class="roster-row"><div><h3>{{ s.team.name }}</h3><p>{{ s.season.name }}</p></div><small class="muted">{{ s.joinedAt.slice(0, 10) }}<br>{{ s.leftAt?.slice(0, 10) ?? 'Actualidad' }}</small></div><StateNotice :empty="!player.squads.length" /></section></div><section v-if="params.organizationId" class="panel section-gap"><h2>Evaluaciones del club</h2><form v-if="canEvaluate" class="editor-form section-gap" @submit.prevent="evaluate"><label>Temporada<select v-model="seasonId" required><option value="">Seleccionar</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label>Puntuación (0–10)<input v-model.number="rating" required type="number" min="0" max="10" step="0.1"></label><label>Observaciones<textarea v-model="notes" maxlength="4000" required /></label><button class="button primary">Guardar evaluación</button></form><div v-for="r in reports" :key="r.id" class="report-row"><strong class="accent">{{ r.rating }} / 10</strong><p>{{ r.notes }}</p><small class="muted">{{ new Date(r.createdAt).toLocaleDateString('es') }}</small></div></section></template></section></template>
